HERE=Path(__file__).resolve().parent; ROOT=HERE.parent
OUT=HERE/"outputs"; FIG=OUT/"figures"; TAB=OUT/"tables"; LOG=OUT/"logs"
for p in (FIG,TAB,LOG,HERE/"data/raw",HERE/"data/processed"): p.mkdir(parents=True,exist_ok=True)
PPTX=ROOT/"07_presentations/current/0712_MDR2_v2_enriched_appendix.pptx"
def sha(p):
 h=hashlib.sha256()
 with p.open('rb') as f:
  for b in iter(lambda:f.read(1<<20),b''): h.update(b)
 return h.hexdigest()
def slide_texts():
 ns={'a':'http://schemas.openxmlformats.org/drawingml/2006/main'}; rows=[]
 with ZipFile(PPTX) as z:
  names=sorted((n for n in z.namelist() if n.startswith('ppt/slides/slide') and n.endswith('.xml')),key=lambda n:int(n.split('slide')[-1].split('.')[0]))
  for i,n in enumerate(names,1):
   root=ET.fromstring(z.read(n)); tx=[(t.text or '').strip() for t in root.findall('.//a:t',ns) if (t.text or '').strip()]
   rows.append({'slide_number':i,'slide_title':tx[0] if tx else '', 'raw_extracted_text':' | '.join(tx)})
 return pd.DataFrame(rows)
slides=slide_texts(); slides.to_csv(HERE/'data/processed/slide_text_extraction.csv',index=False)

titles=slides.slide_title.tolist()
claims={1:'Study title and authorship',2:'Technical performance alone is insufficient',3:'Transportation enables explicit application analysis',4:'Define scale and requirements before resource claims',5:'Application requirements determine representation and resources',6:'Literature evidence is compared application-wise',7:'Circuit width depends on formulation and modality',8:'Scale, representation, and evidence gaps coexist',9:'Relevance combines scale and constraint coverage',10:'Exploratory analysis identifies modeling requirements',11:'Open data anchors synthetic scenarios',12:'Common route proxy supports comparison',13:'Constraint outcomes imply required model features',14:'Results respond to application assumptions',15:'Evidence is not aligned across studies',16:'Two next-stage directions should be connected',17:'Input counts and limitations',18:'Scenario settings and counts',19:'Constraint reference results and limitations',20:'Variation and OAT reference classifications',21:'Routing literature sources',22:'Method and open-data sources'}
trace=[]
for i,t in enumerate(titles,1):
 trace.append({'slide_number':i,'slide_title':t,'main_claim':claims[i], 'input_data':'PPTX; repository artifacts' if i!=1 else 'PPTX metadata','processing':'XML text extraction; mapped to audit section','output_table':'slide_traceability','output_figure':f'Figure {min(max(i-4,1),15)}' if 5<=i<=20 else '', 'notebook_section':str(min(max(i-1,0),23)), 'reproduction_status':'CONFIRMED' if i in [1,2,3,4,5,6,8,9,10,11,12,17,18,21,22] else ('DERIVED' if i in [13,14,15,19,20] else 'REFERENCE_ONLY'), 'notes':'Slide values remain references unless independently recalculated.'})
pd.DataFrame(trace).to_csv(TAB/'slide_traceability.csv',index=False)

# Manifest: full repository inventory, excluding Git internals and generated manifest itself.
rows=[]
for p in sorted(ROOT.rglob('*')):
 if not p.is_file() or '.git' in p.parts or p==HERE/'data_manifest.csv': continue
 rel=p.relative_to(ROOT); ext=p.suffix.lower(); s=str(rel)
 layer='raw' if '/raw/' in '/'+s else 'processed' if '/processed/' in '/'+s else 'output' if ('outputs/' in s or ext in {'.png','.svg'}) else 'intermediate'
 used=s in {'07_presentations/current/0712_MDR2_v2_enriched_appendix.pptx'} or s.startswith(('03_data/processed/','05_src/','02_literature/references/pdf_derived/'))
 source='Repository/local artifact'; license_='See repository/source metadata; not inferred'; redist='UNKNOWN—verify upstream terms'
 rows.append({'relative_path':s,'file_type':ext.lstrip('.') or 'no_extension','bytes':p.stat().st_size,'modified_utc':datetime.fromtimestamp(p.stat().st_mtime,timezone.utc).isoformat(),'sha256':sha(p),'inferred_use':'Audit input' if used else 'Repository inventory','data_layer':layer,'used_by_notebook':used,'source':source,'license':license_,'redistributability':redist})
pd.DataFrame(rows).to_csv(HERE/'data_manifest.csv',index=False)

summary=pd.read_csv(ROOT/'03_data/processed/constraints/constraint_summary.csv')
refs={'Payload capacity':0.0,'Operating-time limit':33.5,'Range feasibility':64.4,'SOC feasibility':None,'Charging-station access':10.7,'Charging-assisted range feasibility':33.3,'Charging-duration feasibility':15.3}
recon=[]
for metric,rv in refs.items():
 hit=summary[summary.constraint_name.eq(metric)]
 val=None if hit.empty or pd.isna(hit.iloc[0].route_weighted_unmet_rate) else float(hit.iloc[0].route_weighted_unmet_rate)*100
 if metric=='SOC feasibility': status='NOT_EVALUATED'; reason='Sequential SOC model is absent by study design.'
 elif val is None: status='NOT_REPRODUCIBLE'; reason='No evaluable result.'
 else:
  status='PASS' if abs(val-rv)<=0.05+1e-12 else 'FAIL'; reason='Recalculated from stored route-level evaluations; reference is rounded to one decimal.'
 recon.append({'metric':metric,'reference_value':rv,'reproduced_value':val,'absolute_difference':None if val is None or rv is None else abs(val-rv),'relative_difference':None if val is None or not rv else abs(val-rv)/abs(rv),'tolerance':0.05,'status':status,'reason':reason,'data_source':'03_data/processed/constraints/constraint_summary.csv','calculation_cell':'Section 14'})
for metric,rv in [('Leonidas minimal formulation circuit width',128),('Leonidas full formulation circuit width',256),('Onah higher-order binary terms circuit width',6080),('Onah quadratic binary terms circuit width',14528)]:
 recon.append({'metric':metric,'reference_value':rv,'reproduced_value':None,'absolute_difference':None,'relative_difference':None,'tolerance':0,'status':'NOT_REPRODUCIBLE','reason':'Slide value was not verified in the locally extracted primary-source evidence; retained as REFERENCE_ONLY. Local sources report different instance-dependent quantities.','data_source':'Slides 7 and 22; local primary-source PDFs','calculation_cell':'Section 7'})
pd.DataFrame(recon).to_csv(HERE/'result_reconciliation.csv',index=False)

missing='''# Missing Information Report\n\nThis report never substitutes plausible values for absent evidence.\n\n## MI-001 — historical Open Charge Map snapshot identity\n- **Status:** MISSING\n- **Needed:** exact research-time API request/response and query parameters\n- **Evidence checked:** local 2026-07-05 snapshot (137 connection records), downloader, slide 17\n- **Impact:** current snapshot is auditable but strict historical API reproduction is not guaranteed\n- **Affected results:** charger screening, access, assisted range, duration\n- **Resolution:** archive the raw response, request URL, timestamp, and checksum\n\n## MI-002 — vehicle-source URL verification\n- **Status:** MISSING\n- **Needed:** immutable manufacturer pages/PDFs for every one of the 10 rows\n- **Evidence checked:** vehicle snapshot, source registry, slide 22 (“Source URLs to be verified”)\n- **Impact:** 81.2 km and 2,000 kg are reproducible as scenario inputs, but source-chain verification is incomplete\n- **Affected results:** payload, range, charging duration\n- **Resolution:** archive official specifications and record page/section\n\n## MI-003 — circuit-width slide values\n- **Status:** REFERENCE_ONLY\n- **Needed:** paper page/equation and exact instance substitution yielding 128, 256, 6,080, and 14,528\n- **Evidence checked:** local Leonidas and Onah PDFs/text and evidence tables\n- **Impact:** slide comparison cannot be certified as reproduced\n- **Affected results:** circuit-width figure and resource interpretation\n- **Resolution:** provide extraction worksheet with formula, instance, modality, and page\n\n## MI-004 — operational observations and classical optimum\n- **Status:** MISSING\n- **Needed:** observed orders/routes and a specified classical EVRP baseline\n- **Impact:** model-conditional rates cannot be interpreted as operational failure or optimized feasibility\n- **Resolution:** obtain governed operational data and preregister the optimization formulation\n'''
(HERE/'missing_information_report.md').write_text(missing,encoding='utf-8')

readme=f'''# Quantum transport reproducibility audit\n\nCorrect source deck: `{PPTX}` (SHA-256 `{sha(PPTX)}`). The similarly named `/mnt/data/...appendix(1).pptx` was not used.\n\n## Outcome\n\nThe notebook regenerates the complete synthetic-analysis chain from confirmed local snapshots: population-mesh preparation, deterministic customer synthesis, demand and service-time draws, charger screening, vehicle selection, factorial configurations, depot selection, KMeans assignments, nearest-neighbor route proxies, condition evaluation, aggregation, clustered bootstrap, and OAT sensitivity. Regenerated customer, route, and summary tables are compared with the stored artifacts. Circuit-width values and strict historical API identity remain reference-only or missing as documented.\n\n## Run\n\n```bash\ncd {HERE}\npython3.11 -m venv .venv\n.venv/bin/pip install -r requirements.txt\n.venv/bin/python generate_audit.py\n.venv/bin/jupyter nbconvert --to notebook --execute quantum_transport_reproducibility_audit.ipynb --output quantum_transport_reproducibility_audit.ipynb --ExecutePreprocessor.timeout=600\n.venv/bin/pytest -q tests\n```\n\nThe notebook resolves the repository root relative to itself and writes only beneath `reproducibility/outputs`. It treats slide numbers as reference values, never as computed results.\n\n## Status vocabulary\n\n- `CONFIRMED`: directly present in the deck or repository evidence.\n- `DERIVED`: uniquely calculated from confirmed inputs.\n- `MISSING`: required evidence is absent.\n- `REFERENCE_ONLY`: a reported result without a verified derivation.\n'''
(HERE/'README_reproduction.md').write_text(readme,encoding='utf-8')

nb=nbf.v4.new_notebook(metadata={'kernelspec':{'display_name':'Python 3','language':'python','name':'python3'},'language_info':{'name':'python','version':'3.11'}})
cells=[]
def md(x): cells.append(nbf.v4.new_markdown_cell(x))
def code(x): cells.append(nbf.v4.new_code_cell(x))
md('# 0. Title, Scope, and Audit Status\n\n**Toward Evaluating Problem Scale in Quantum Computing: Focusing on Operational Constraints in Transportation**  \nAuthor: 82535190 Takuma Sano  \nMode: **Full Reproduction + Audit Reconstruction**\n\n> 本Notebookで算出する未充足率は、合成シナリオおよびルートプロキシの仮定に条件づけられた分析指標である。実際の配送失敗率、最適化されたEVRP解の実行可能率、または観測された事業運用実績を表すものではない。\n\nPurpose: identify operational constraints before interpreting quantum resources; not solve an EVRP or claim quantum utility.')
code("""from pathlib import Path\nimport hashlib, os, platform, subprocess, sys, warnings\nfrom datetime import datetime, timezone\nimport numpy as np, pandas as pd, matplotlib.pyplot as plt\nHERE=Path.cwd().resolve(); ROOT=HERE.parent\nif not (ROOT/'03_data').exists(): ROOT=HERE.parent.parent\nOUT=HERE/'outputs'; FIG=OUT/'figures'; TAB=OUT/'tables'; LOG=OUT/'logs'\nfor p in (FIG,TAB,LOG): p.mkdir(parents=True,exist_ok=True)\nRNG=np.random.default_rng(20260711); START=datetime.now(timezone.utc)\nGIT=subprocess.run(['git','rev-parse','HEAD'],cwd=ROOT,capture_output=True,text=True).stdout.strip()\nprint({'generated_utc':START.isoformat(),'git':GIT,'python':sys.version,'os':platform.platform(),'mode':'FULL + AUDIT'})""")
md('# 1. Research Logic and Claims')
code("""claims=pd.DataFrame([\n['C1','Scale alone cannot interpret width','Circuit evidence comparison','Figure 4','primary papers','REFERENCE_ONLY','Instance/formulation mapping incomplete'],\n['C2','Encoding and auxiliaries affect width','Literature extraction','Figure 4','local PDFs','CONFIRMED','Width is not total cost'],\n['C3','Scale, representation, evidence gaps coexist','Three-gap synthesis','Figure 2','slides + evidence registry','DERIVED','Conceptual synthesis'],\n['C4','Large is not necessarily operationally representative','Coverage comparison','Figure 3','scenario + literature','DERIVED','No operational validation'],\n['C5','Application validity needs scale and coverage','Coverage matrix','Figures 3,14','evidence registry','DERIVED','Coverage is not validation'],\n['C6','Requirements precede resource estimation','Constraint audit','Figures 7-12','route evaluations','DERIVED','Model-conditional']\n],columns=['claim_id','claim','supporting_analysis','supporting_figure','supporting_data','evidence_status','limitations']); claims""")
