code("""cw=pd.DataFrame({'study':['Leonidas minimal','Leonidas full','Onah higher-order','Onah quadratic'],'width':[128,256,6080,14528],'status':['REFERENCE_ONLY']*4})\nfig,ax=plt.subplots(figsize=(8,3.5)); ax.barh(cw.study,cw.width,facecolor='none',edgecolor='black',hatch='//'); ax.set_xscale('log'); ax.set_xlabel('Reported circuit width / qubits (log scale)'); ax.set_title('Figure 4. Slide-reference widths — not independently reproduced'); ax.grid(axis='x',alpha=.3); fig.tight_layout(); fig.savefig(FIG/'figure04_circuit_width.png',dpi=320); fig.savefig(FIG/'figure04_circuit_width.svg'); plt.show(); cw""")
md('# 8. Scenario Configuration and Full Synthesis\n\nThis section performs the synthesis itself. It does not load the stored synthetic-customer or route-result CSV as an analytical input. The stored files are read only after regeneration for regression comparison.')
code("""import sys\nfor module_dir in [ROOT/'05_src/scenario_generation',ROOT/'05_src/sensitivity']:\n sys.path.insert(0,str(module_dir)) if str(module_dir) not in sys.path else None\nfrom scenario_utils import (BaselineAssumptions,prepare_population_mesh,generate_synthetic_customers,build_charger_condition_definitions,build_eligible_charger_candidates,select_baseline_vehicle,build_analysis_configurations,construct_route_proxies,evaluate_routes_by_condition)\nfrom monte_carlo_utils import build_constraint_evaluations,build_case_rates,cluster_bootstrap_constraint_summary,run_oat_sensitivity\nCUSTOMER_COUNTS=[25,50,100]; VEHICLE_COUNTS=[1,3,5]; SEEDS=list(range(1,101))\nassumptions=BaselineAssumptions()\nprint(assumptions)""")
code("""mesh=pd.read_csv(paths['e-Stat']); depots=pd.read_csv(paths['P31']); chargers=pd.read_csv(paths['OCM']); vehicles=pd.read_csv(paths['vehicle'])\nprepared_mesh=prepare_population_mesh(mesh,assumptions)\nassert np.isclose(prepared_mesh.sampling_weight.sum(),1.0)\ncustomers,randomization_registry=generate_synthetic_customers(mesh,CUSTOMER_COUNTS,SEEDS,assumptions)\ncharger_definitions=build_charger_condition_definitions()\ncharger_candidates,charger_definitions=build_eligible_charger_candidates(chargers,charger_definitions)\nbaseline_vehicle=select_baseline_vehicle(vehicles)\ncfg=build_analysis_configurations(CUSTOMER_COUNTS,VEHICLE_COUNTS,charger_definitions,baseline_vehicle,assumptions,len(SEEDS))\nSYN=OUT/'synthesized'; SYN.mkdir(exist_ok=True)\ncustomers.to_csv(SYN/'synthetic_customers.csv',index=False); randomization_registry.to_csv(SYN/'randomization_registry.csv',index=False); charger_definitions.to_csv(SYN/'charger_condition_definitions.csv',index=False); charger_candidates.to_csv(SYN/'eligible_charger_candidates.csv',index=False); cfg.to_csv(SYN/'scenario_configurations.csv',index=False)\n{'eligible_mesh_cells':len(prepared_mesh),'customer_rows':len(customers),'charger_candidates_by_condition':charger_candidates.groupby('charger_condition').charger_candidate_id.nunique().to_dict(),'scenario_configurations':len(cfg),'baseline_vehicle':baseline_vehicle.scenario_vehicle_id}""")
md('# 9. Synthetic Customer Generation\n\nFor every `(customer_count, seed)`, the implementation creates `numpy.random.default_rng(seed × 100000 + customer_count)`, samples positive-population mesh cells without replacement using normalized population weights, then draws integer demand from 5–30 kg and service time from 5–15 minutes. The resulting customer set is shared across all vehicle-count and charger-condition comparisons.')
code("""assert len(customers)==17500 and customers.latitude.between(35.45,35.95).all() and customers.longitude.between(138.85,140.25).all()\ncustomers_repeat,_=generate_synthetic_customers(mesh,[25],[1],assumptions)\npd.testing.assert_frame_equal(customers.query('customer_count==25 and seed==1').reset_index(drop=True),customers_repeat.reset_index(drop=True),check_dtype=False)\nstored_customers=pd.read_csv(ROOT/'03_data/processed/scenario/synthetic_customers.csv'); stored_customers['mesh_code']=stored_customers['mesh_code'].astype(str)\npd.testing.assert_frame_equal(customers.reset_index(drop=True),stored_customers.reset_index(drop=True),check_dtype=False,rtol=1e-12,atol=1e-12)\nfig,ax=plt.subplots(figsize=(7,6)); ax.scatter(customers.longitude.iloc[::20],customers.latitude.iloc[::20],s=3,label='Synthetic customers (1/20 shown)',alpha=.5); ax.scatter(chargers.longitude,chargers.latitude,s=15,marker='^',label='Charger connections'); ax.set(xlabel='Longitude',ylabel='Latitude',title='Figure 5. Population-weighted synthetic customer spatial proxy'); ax.legend(); fig.tight_layout(); fig.savefig(FIG/'figure05_customer_map.png',dpi=320); fig.savefig(FIG/'figure05_customer_map.svg'); plt.show()""")
