md('# 11. Route-Proxy Construction\n\nThe cells below execute KMeans assignment (`random_state=seed`, `n_init=20`), deterministic nearest-neighbor ordering, depot selection nearest to each customer-set centroid, depot return, Haversine distance (Earth radius 6371.0088 km), and the confirmed 1.25 road multiplier. They then execute all three charger-condition evaluations. This remains a proxy, not a road-network path or optimized EVRP solution.')
code("""base_routes,route_edges,route_members=construct_route_proxies(customers,depots,CUSTOMER_COUNTS,VEHICLE_COUNTS,SEEDS,assumptions)\nroutes=evaluate_routes_by_condition(base_routes,route_members,cfg,charger_candidates,baseline_vehicle,assumptions)\nfor name,frame in {'base_route_proxy_results':base_routes,'route_proxy_edges':route_edges,'route_proxy_members':route_members,'route_proxy_results':routes}.items(): frame.to_csv(SYN/f'{name}.csv',index=False)\ncounts={'configurations':len(cfg),'condition_evaluations':routes[['scenario_id','seed']].drop_duplicates().shape[0],'route_condition_evaluations':len(routes),'synthetic_customer_records':len(customers)}\nassert counts=={'configurations':27,'condition_evaluations':2700,'route_condition_evaluations':8100,'synthetic_customer_records':17500}\nstored_routes=pd.read_csv(ROOT/'03_data/processed/route_proxy/route_proxy_results.csv')\nassert list(routes.columns)==list(stored_routes.columns)\nfor column in routes.columns:\n if pd.api.types.is_numeric_dtype(routes[column]) and not pd.api.types.is_bool_dtype(routes[column]):\n  assert np.allclose(pd.to_numeric(routes[column],errors='coerce'),pd.to_numeric(stored_routes[column],errors='coerce'),rtol=1e-10,atol=1e-10,equal_nan=True),column\n else:\n  left=routes[column].astype('string').fillna('<NA>'); right=stored_routes[column].astype('string').fillna('<NA>'); assert left.equals(right),column\ncounts""")
code("""sample=routes.query('customer_count==25 and vehicle_count==3 and seed==1 and charger_condition==\"balanced\"'); fig,ax=plt.subplots(figsize=(7,6)); ax.scatter(customers.query('customer_count==25 and seed==1').longitude,customers.query('customer_count==25 and seed==1').latitude,label='Customers'); d=depots[depots.scenario_depot_id.isin(sample.depot_candidate_id)]; ax.scatter(d.longitude,d.latitude,marker='s',s=70,label='Selected depot proxy'); ax.scatter(chargers.longitude,chargers.latitude,marker='^',s=12,label='Charger candidates',alpha=.5); ax.set(xlabel='Longitude',ylabel='Latitude',title='Figure 6. Route-proxy context (not actual route geometry)'); ax.legend(); fig.tight_layout(); fig.savefig(FIG/'figure06_route_context.png',dpi=320); fig.savefig(FIG/'figure06_route_context.svg'); plt.show()""")
