code("""def grouped(col):\n g=ev[ev.evaluated.astype(str).str.lower().eq('true')].copy(); g['unmet_i']=g.unmet.astype(str).str.lower().eq('true').astype(int); return g.groupby([col,'constraint_name']).unmet_i.agg(['mean','count','std','min','max']).reset_index()\nfor n,col in enumerate(['customer_count','vehicle_count','charger_condition'],8):\n g=grouped(col); display(g.head()); fig,ax=plt.subplots(figsize=(9,4));\n for key,z in g.groupby('constraint_name'): ax.plot(z[col].astype(str),z['mean']*100,marker='o',label=key)\n ax.set(xlabel=col,ylabel='Unmet rate (%)',title=f'Figure {n}. Unmet rate by {col} (denominators in table)'); ax.legend(fontsize=6,ncol=2); fig.tight_layout(); fig.savefig(FIG/f'figure{n:02d}_{col}.png',dpi=320); fig.savefig(FIG/f'figure{n:02d}_{col}.svg'); plt.show()""")
