md('# 17. One-at-a-Time Sensitivity Analysis')
code("""parameters=pd.read_csv(ROOT/'03_data/processed/evrp_constraint_gap_inputs/analysis_parameters.csv'); sens,parameter_response=run_oat_sensitivity(routes,parameters,baseline_vehicle); sens.to_csv(SYN/'sensitivity_summary.csv',index=False); parameter_response.to_csv(SYN/'parameter_response_table.csv',index=False)\nfig,ax=plt.subplots(figsize=(9,5)); top=sens.groupby(['parameter','constraint_name']).unmet_rate_change_from_base.apply(lambda s:s.abs().max()).reset_index(); piv=top.pivot(index='constraint_name',columns='parameter',values='unmet_rate_change_from_base').fillna(0); im=ax.imshow(piv,aspect='auto',cmap='Greys'); ax.set_xticks(range(len(piv.columns)),piv.columns,rotation=60,ha='right'); ax.set_yticks(range(len(piv.index)),piv.index); ax.set_title('Figure 12. Maximum absolute OAT change'); fig.colorbar(im,ax=ax,label='Absolute rate change'); fig.tight_layout(); fig.savefig(FIG/'figure12_oat.png',dpi=320); fig.savefig(FIG/'figure12_oat.svg'); plt.show(); piv""")
