code("""# Figures 1–3 and 7 are generated directly from the study logic/results.\ndef save_simple(num,title,labels):\n fig,ax=plt.subplots(figsize=(9,3)); ax.axis('off'); xs=np.linspace(.1,.9,len(labels));\n for x,l in zip(xs,labels): ax.text(x,.5,l,ha='center',va='center',bbox=dict(boxstyle='round',fc='white',ec='black'));\n for a,b in zip(xs[:-1],xs[1:]): ax.annotate('',(b-.05,.5),(a+.05,.5),arrowprops={'arrowstyle':'->'}); ax.set_title(f'Figure {num}. {title}'); fig.tight_layout(); fig.savefig(FIG/f'figure{num:02d}_concept.png',dpi=320); fig.savefig(FIG/f'figure{num:02d}_concept.svg'); plt.show()\nsave_simple(1,'Research causal structure',['Application','Representation','Encoding','Resources','Technology stage']); save_simple(2,'Application–technology gaps',['Scale gap','Representation gap','Evidence gap']); save_simple(3,'Application relevance',['Problem scale','Constraint coverage','Representative requirements'])\nfig,ax=plt.subplots(figsize=(8,4)); z=summary.dropna(subset=['route_weighted_unmet_rate']); ax.barh(z.constraint_name,z.route_weighted_unmet_rate*100,facecolor='white',edgecolor='black',hatch='//'); ax.set(xlabel='Route-weighted unmet rate (%)',title='Figure 7. Constraint results (n varies by constraint)'); fig.tight_layout(); fig.savefig(FIG/'figure07_constraint_rates.png',dpi=320); fig.savefig(FIG/'figure07_constraint_rates.svg'); plt.show()""")
